if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { await main(process.argv.slice(2)); }
  catch (error) { console.error(JSON.stringify({ error: error instanceof RunnerFailure ? error.code : 'CONTENT_TOOL_FAILED' })); process.exitCode = 1; }
}
